// Scratch: reproduces the user report with the current Add signature.
func TestScratch_AddRetryWithStreamedMultipart(t *testing.T) {
	var calls int
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{MaxAttempts: 3, BaseDelay: time.Millisecond, RetryAllMethods: true},
	}, func(w http.ResponseWriter, r *http.Request) {
		calls++
		if calls == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12}}`))
	})

	// Simulate the user: multipart body streamed from a pipe (non-replayable).
	pr, pw := io.Pipe()
	go func() {
		mw := multipart.NewWriter(pw)
		part, _ := mw.CreateFormFile("file", "upload.txt")
		_, _ = io.Copy(part, strings.NewReader("file content"))
		_ = mw.Close()
		_ = pw.Close()
	}()

	_, err := client.Files.Add(context.Background(), pr, mwContentType(t, "upload.txt"))
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if calls != 2 {
		t.Fatalf("expected 2 calls (retry on 429), got %d", calls)
	}
}

func mwContentType(t *testing.T, name string) string {
	t.Helper()
	var buf strings.Builder
	mw := multipart.NewWriter(&buf)
	_, _ = mw.CreateFormFile("file", name)
	_ = mw.Close()
	return mw.FormDataContentType()
}

