func TestFilesService_Update(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPut {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files/5" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("Content-Type"); got != "application/x-www-form-urlencoded" {
			t.Fatalf("unexpected content type: %q", got)
		}
		if err := r.ParseForm(); err != nil {
			t.Fatalf("parse form: %v", err)
		}
		if got := r.Form.Get("name"); got != "updated" {
			t.Fatalf("unexpected name: %q", got)
		}
		if got := r.Form.Get("description"); got != "quarterly report" {
			t.Fatalf("unexpected description: %q", got)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":5,"name":"updated"}}`))
	})

	file, err := client.Files.Update(context.Background(), FileID(5), "updated", "quarterly report")
	if err != nil {
		t.Fatalf("Update error: %v", err)
	}
	if file.ID != 5 || file.Name != "updated" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func decodeMultipartForm(t *testing.T, r *http.Request) url.Values {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected content type: %q", mediaType)
	}
	form, err := multipart.NewReader(r.Body, params["boundary"]).ReadForm(1 << 20)
	if err != nil {
		t.Fatalf("read multipart form: %v", err)
	}
	return form.Value
}

func decodeMultipartFile(t *testing.T, r *http.Request, field string) struct {
	FileName string
	Content  string
} {
	t.Helper()

	form := decodeMultipartForm(t, r)
	parts := form.File[field]
	if len(parts) != 1 {
		t.Fatalf("expected 1 %q file part, got %d", field, len(parts))
	}
	fh, err := parts[0].Open()
	if err != nil {
		t.Fatalf("open file part: %v", err)
	}
	defer fh.Close()
	content, err := io.ReadAll(fh)
	if err != nil {
		t.Fatalf("read file part: %v", err)
	}
	return struct {
		FileName string
		Content  string
	}{parts[0].Filename, string(content)}
}

