func decodeMultipartForm(t *testing.T, r *http.Request) url.Values {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected content type: %q", mediaType)
	}
	form, err := multipart.NewReader(r.Body, params["boundary"]).ReadForm(1 << 20)
	if err != nil {
		t.Fatalf("read multipart form: %v", err)
	}
	return form.Value
}

func decodeMultipartFile(t *testing.T, r *http.Request, field string) struct {
	FileName string
	Content  string
} {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected content type: %q", mediaType)
	}
	form, err := multipart.NewReader(r.Body, params["boundary"]).ReadForm(1 << 20)
	if err != nil {
		t.Fatalf("read multipart form: %v", err)
	}
	parts := form.File[field]
	if len(parts) != 1 {
		t.Fatalf("expected 1 %q file part, got %d", field, len(parts))
	}
	fh, err := parts[0].Open()
	if err != nil {
		t.Fatalf("open file part: %v", err)
	}
	defer fh.Close()
	content, err := io.ReadAll(fh)
	if err != nil {
		t.Fatalf("read file part: %v", err)
	}
	return struct {
		FileName string
		Content  string
	}{parts[0].Filename, string(content)}
}

